&lt;p data-renderer-start-pos=&quot;706&quot; data-local-id=&quot;6d17a07f558d&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;Job Responsibilities:&lt;br&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
